import { Tabs } from '@refy-design/web';
import type { ComponentProps } from 'react';
const items = [
  {
    id: 'general',
    label: 'Overview',
    content: <p style={{ color: 'var(--ink-2)' }}>Coverage panel.</p>,
  },
  {
    id: 'issues',
    label: 'Issues',
    badge: 14,
    content: <p style={{ color: 'var(--ink-2)' }}>14 issues mapped.</p>,
  },
  {
    id: 'backlog',
    label: 'Tasks',
    badge: 23,
    content: <p style={{ color: 'var(--ink-2)' }}>Tasks prioritized.</p>,
  },
  {
    id: 'hist',
    label: 'History',
    content: <p style={{ color: 'var(--ink-2)' }}>Previous analyses.</p>,
  },
];
export function Example() {
  const args: Pick<ComponentProps<typeof Tabs>, 'items' | 'orientation'> = {
    items: [
